package ammonite.compiler

import dotty.tools.dotc
import dotc.ast.tpd
import dotc.core.Constants.Constant
import dotc.core.Contexts._
import dotc.core.Flags
import dotc.core.NameOps._
import dotc.core.Symbols.Symbol
import dotc.core.Types._
import dotc.printing.ReplPrinter

import scala.util.Try

/**
 * Fills the types of the values printed by the REPL.
 *
 * The code generated by [[Preprocessor]] prints values with calls like
 * {{{
 *   ReplBridge.value.Internal.printTyped(x, "x", None, "", "")
 * }}}
 * Once the code is typed, we replace the first empty string by the type of `x`, rendered
 * by the compiler the way the dotty REPL does it (so that we get `Int | String` or
 * `(name : String, age : Int)`, rather than what pprint's `TPrint` gives), and the second
 * one by the field names of `x` if it's a named tuple, so that its value can be printed
 * along with its field names.
 */
object ResultTypes {

  /** Must be the same as `ammonite.repl.FullReplAPI.printTypedFieldSeparator` */
  private final val fieldSeparator = "\u0000"

  /** The full name of sym, without the '$' of module classes */
  private def fullName(sym: Symbol)(using Context): String =
    sym.fullName.toString.replace("$", "")

  private def isWrapperPackage(sym: Symbol)(using Context): Boolean =
    sym.is(Flags.Package) && {
      val name = sym.fullName.toString
      name == "ammonite" || name.startsWith("ammonite.$")
    }

  private def isWrapperClass(sym: Symbol)(using Context): Boolean =
    sym.exists && sym.isClass && (
      isWrapperPackage(sym.owner) ||
        (sym.name.stripModuleClassSuffix.toString == "Helper" && isWrapperClass(sym.owner))
    )

  /**
   * Whether `sym` is part of the code Ammonite wraps user code in: a package such as
   * `ammonite.$sess`, a `cmd1` wrapper object or class, its `Helper`, or a value
   * referencing one of these (like the `cmd1` vals of class-based wrappers).
   */
  def isWrapper(sym: Symbol)(using Context): Boolean =
    Try {
      sym.exists && (
        isWrapperPackage(sym) ||
          isWrapperClass(sym) ||
          (sym.isTerm && !sym.is(Flags.Method) && (
            isWrapperClass(sym.moduleClass) ||
              isWrapperClass(sym.info.widen.classSymbol)
          ))
      )
    }.getOrElse(false)

  /** dotty's REPL printer, that also leaves out the Ammonite wrapper prefixes */
  private class Printer(ctx0: Context) extends ReplPrinter(ctx0) {
    override protected def isEmptyPrefix(sym: Symbol): Boolean =
      super.isEmptyPrefix(sym) || isWrapper(sym)(using ctx0)

    // Static objects (like `object Outer` in the object-based wrappers) are printed
    // with their full name, that ReplPrinter computes without isEmptyPrefix
    override def fullNameString(sym: Symbol): String = {
      given Context = ctx0
      def relativeToWrapper(sym: Symbol): Option[String] =
        if (!sym.exists || sym.is(Flags.Package)) None
        else {
          val owner = sym.effectiveOwner
          if (isWrapper(owner)) Some(nameString(sym))
          else {
            val owner0 = if (owner.is(Flags.ModuleClass)) owner.sourceModule else owner
            relativeToWrapper(owner0).map(_ + "." + nameString(sym))
          }
        }
      relativeToWrapper(sym).getOrElse(super.fullNameString(sym))
    }
  }

  def show(tpe: Type)(using ctx: Context): String = {
    val printCtx = ctx.fresh
      .setPrinterFn(new Printer(_))
      .setSetting(ctx.settings.pageWidth, Int.MaxValue / 2)
    tpe.show(using printCtx)
  }

  private def stringConstants(tpe: Type)(using Context): Option[List[String]] =
    tpe.dealias match {
      case ConstantType(Constant(s: String)) => Some(List(s))
      case AppliedType(tycon, args) =>
        val name = fullName(tycon.typeSymbol)
        if (name == "scala.*:")
          args match {
            case List(head, tail) =>
              for {
                h <- stringConstants(head)
                t <- stringConstants(tail)
              } yield h ::: t
            case _ => None
          }
        else if (name.startsWith("scala.Tuple"))
          args.foldRight(Option(List.empty[String])) { (arg, acc) =>
            for {
              l <- acc
              h <- stringConstants(arg)
            } yield h ::: l
          }
        else None
      case tpe if fullName(tpe.termSymbol) == "scala.EmptyTuple" =>
        Some(Nil)
      case tpe if fullName(tpe.typeSymbol) == "scala.EmptyTuple" =>
        Some(Nil)
      case _ => None
    }

  /** The field names of `tpe`, if it's a named tuple */
  def namedTupleFields(tpe: Type)(using Context): Option[List[String]] =
    Try {
      tpe.widenDealias match {
        case AppliedType(tycon, List(names, _))
            if fullName(tycon.typeSymbol) == "scala.NamedTuple.NamedTuple" =>
          stringConstants(names)
        case _ => None
      }
    }.toOption.flatten

  private def isPrintTyped(sym: Symbol)(using Context): Boolean =
    sym.exists && sym.name.toString == "printTyped" &&
      fullName(sym.owner) == "ammonite.repl.FullReplAPI.Internal"

  private def isEmptyString(tree: tpd.Tree): Boolean =
    tree match {
      case tpd.Literal(Constant("")) => true
      case _ => false
    }

  private def typeOf(value: tpd.Tree, targ: tpd.Tree)(using Context): Type = {
    // Like the dotty REPL, show the type of the val being printed, rather than
    // the type inferred for the type parameter of printTyped, which can be widened
    // (singleton types, for example)
    val sym = value.symbol
    if (sym.exists && sym.isTerm && !sym.is(Flags.Method)) sym.info.widenExpr
    else targ.tpe
  }

  private object Filler extends tpd.TreeMap {
    // Keep track of the imports in scope, so that the printer can use them to
    // shorten type names (like scalac's TPrint does on Scala 2)
    override def transformStats(trees: List[tpd.Tree], exprOwner: Symbol)(using
        Context
    ): List[tpd.Tree] = {
      var statsCtx = ctx
      trees.map {
        case imp: tpd.Import =>
          statsCtx = statsCtx.importContext(imp, imp.symbol)
          imp
        case tree =>
          transform(tree)(using statsCtx)
      }
    }

    override def transform(tree: tpd.Tree)(using Context): tpd.Tree =
      tree match {
        case app @ tpd.Apply(
              fun @ tpd.TypeApply(sel, List(targ)),
              List(value, ident, custom, tpe, fields)
            ) if isPrintTyped(sel.symbol) && isEmptyString(tpe) && isEmptyString(fields) =>
          val valueType = typeOf(value, targ)
          val typeStr = Try(show(valueType))
            .orElse(Try(show(targ.tpe)))
            .getOrElse("?")
          val fieldsStr = namedTupleFields(valueType)
            .fold("")(_.mkString(fieldSeparator))
          val newArgs = List(
            transform(value),
            ident,
            custom,
            tpd.Literal(Constant(typeStr)).withSpan(tpe.span),
            tpd.Literal(Constant(fieldsStr)).withSpan(fields.span)
          )
          tpd.cpy.Apply(app)(fun, newArgs)
        case _ =>
          super.transform(tree)
      }
  }

  def fill(tree: tpd.Tree)(using Context): tpd.Tree =
    Filler.transform(tree)
}
